bash -c 'show_urls(){ if [ ! -f /tmp/serveo_selkies.log ] || ! grep -q "serveousercontent" /tmp/serveo_selkies.log 2>/dev/null; then [ -f /tmp/serveo.pid ] && kill $(cat /tmp/serveo.pid) 2>/dev/null; rm -f /tmp/serveo_selkies.log; nohup ssh -o StrictHostKeyChecking=no -o ServerAliveInterval=30 -R 80:localhost:3000 serveo.net > /tmp/serveo_selkies.log 2>&1 & echo $! > /tmp/serveo.pid; for i in {1..10}; do grep -q "serveousercontent" /tmp/serveo_selkies.log 2>/dev/null && break; sleep 0.5; done; fi; echo -e "\n=== Selkies Access URLs ==="; echo "Local URL:  http://localhost:3000"; echo "Serveo URL: $(grep -o -E "https?://[a-zA-Z0-9.-]+\.serveousercontent\.com/?" /tmp/serveo_selkies.log 2>/dev/null | head -n 1)"; }; STATUS=$(docker inspect -f "{{.State.Running}}" debian-selkies 2>/dev/null); if [ -z "$STATUS" ]; then echo "Container not found. Installing and starting..." && docker run -d --name debian-selkies -p 3000:3000 -p 3001:3001 --shm-size="5gb" -v /tmp:/tmp -e PUID=1000 -e PGID=1000 --restart unless-stopped lscr.io/linuxserver/baseimage-selkies:debianbookworm && show_urls; elif [ "$STATUS" = "true" ]; then echo "Container is already running."; show_urls; else read -p "Container is currently stopped. Start it? (y/N): " ANS; if [[ "$ANS" =~ ^[Yy]$ ]]; then docker start debian-selkies && show_urls; else echo "Exiting without starting container."; fi; fi'
